def pair_with_sum(prices, target):
    l, r = 0, len(prices) - 1
    while l < r:
        s = prices[l] + prices[r]
        if s == target:
            return (prices[l], prices[r])
        if s < target:
            l += 1
        else:
            r -= 1
    return None

def best_streak_sales(sales, k):
    if k > len(sales) or k <= 0:
        return 0
    cur = sum(sales[:k])
    best = cur
    for i in range(k, len(sales)):
        cur += sales[i] - sales[i - k]
        best = max(best, cur)
    return best

def min_rate(loads, hours):
    lo, hi = 1, max(loads)
    while lo < hi:
        mid = (lo + hi) // 2
        if sum(-(-x // mid) for x in loads) <= hours:
            hi = mid
        else:
            lo = mid + 1
    return lo

def first_unique_char(s):
    from collections import Counter
    c = Counter(s)
    for i, ch in enumerate(s):
        if c[ch] == 1:
            return i
    return -1

def valid_brackets(s):
    pair = {')': '(', ']': '[', '}': '{'}
    st = []
    for ch in s:
        if ch in '([{':
            st.append(ch)
        elif ch in pair:
            if not st or st.pop() != pair[ch]:
                return False
    return not st

def min_steps(grid):
    from collections import deque
    R, C = len(grid), len(grid[0])
    if grid[0][0] == '#' or grid[R-1][C-1] == '#':
        return -1
    q, seen = deque([(0, 0, 0)]), {(0, 0)}
    while q:
        r, c, d = q.popleft()
        if (r, c) == (R - 1, C - 1):
            return d
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == '.' and (nr, nc) not in seen:
                seen.add((nr, nc))
                q.append((nr, nc, d + 1))
    return -1

def count_islands(grid):
    if not grid:
        return 0
    R, C = len(grid), len(grid[0])
    seen = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            a, b = stack.pop()
            if (a, b) in seen or not (0 <= a < R and 0 <= b < C) or grid[a][b] != '1':
                continue
            seen.add((a, b))
            stack += [(a + 1, b), (a - 1, b), (a, b + 1), (a, b - 1)]
    n = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] == '1' and (r, c) not in seen:
                n += 1
                dfs(r, c)
    return n

def k_largest(nums, k):
    import heapq
    return heapq.nlargest(k, nums)

def subsets(nums):
    res = []
    def go(i, cur):
        if i == len(nums):
            res.append(cur[:])
            return
        go(i + 1, cur)
        cur.append(nums[i])
        go(i + 1, cur)
        cur.pop()
    go(0, [])
    return sorted(res, key=lambda s: (len(s), s))

def coin_change_min(coins, amount):
    INF = float('inf')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return -1 if dp[amount] == INF else dp[amount]

def max_meetings(intervals):
    count, end = 0, float('-inf')
    for s, e in sorted(intervals, key=lambda x: x[1]):
        if s >= end:
            count += 1
            end = e
    return count

def merge_intervals(iv):
    out = []
    for s, e in sorted(iv):
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

def count_components(n, edges):
    p = list(range(n))
    def find(x):
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x
    comps = n
    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra != rb:
            p[ra] = rb
            comps -= 1
    return comps
